/* PoP Phase D.2 / P018: the display sink of the separate Wine process.
 *
 * win32u's console driver (ps5drv.c, generated by tools/build-win32u-ps4.py) composes this process's windows
 * and hands the result to a sink. The title's sink (platform/ps4/pw_wine_sink_ps4.c) owns VideoOut; this
 * process must never open it. This sink reports layered presentation, so the driver passes the stack of
 * this process's shown windows (bottom first, screen rectangle + pixels) on every flush, move and destroy.
 * A presenter thread sends the latest top window over the title's surface socket (native/pop_separate.h POP_SEP_SURFACE,
 * struct pop_sep_frame), where the title composites it at that rectangle (native/pop_loader_spawn.h).
 * No stack (the last window went away) closes the connection, which removes the picture in the title.
 *
 * D.2 scope: one window, the top of the stack. Several windows and their z-order against the title's own
 * windows are D.3 work. Pixels no paint has reached yet (PS5_UNPAINTED) are sent as dark grey. */
#include <errno.h>
#include <pthread.h>
#include <signal.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <unistd.h>
#include "pop_separate.h"

struct pw_wine_layer {const uint32_t *pixels;int left,top,right,bottom;unsigned stride,flags,source_width,source_height;};
struct PwWineInput;
#define PS5_UNPAINTED 0x01ff00ffu
#define PS5_LAYER_IMAGE 1

static pthread_mutex_t sink_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t surface_ready = PTHREAD_COND_INITIALIZER;
static int surface_fd = -1;
static unsigned long frames_sent, connects;
static int surface_started, frame_pending;
static unsigned long frames_replaced, frames_dropped;
struct surface_frame {
    struct pop_sep_frame header;
    uint32_t *pixels;
    size_t capacity;
};
static struct surface_frame pending;
static uint32_t shown_hwnd;   /* the last window win32u showed: D.3 routes the title's clicks to it */

#ifdef __ORBIS__
extern int pw_wine_pthread_sigmask(int, const sigset_t *, sigset_t *);
#else
#define pw_wine_pthread_sigmask pthread_sigmask
#endif

/* log through the PRX entry's log (native/pop_wine_child.c) */
extern void pop_wine_child_log(const char *line);
static void slog(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
#include <stdarg.h>
static void slog(const char *fmt, ...){
    char line[300]; va_list ap; va_start(ap, fmt); vsnprintf(line, sizeof(line), fmt, ap); va_end(ap);
    pop_wine_child_log(line);
}

/* OpenOrbis' sockaddr_un has no sun_len; the kernel reads byte 0 as the length and byte 1 as the family */
static int surface_connect(void){
    unsigned char addr[128]; size_t n = strlen(POP_SEP_SURFACE);
    if(n + 3 > sizeof(addr)) return -1;
    memset(addr, 0, sizeof(addr)); addr[0] = (unsigned char)(2 + n + 1); addr[1] = AF_UNIX; memcpy(addr + 2, POP_SEP_SURFACE, n);
    int fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if(fd < 0) return -1;
    int one = 1; setsockopt(fd, SOL_SOCKET, 0x1022 /* SO_NOSIGPIPE */, &one, sizeof(one));
    if(connect(fd, (struct sockaddr *)addr, (socklen_t)(2 + n + 1))){ int e = errno; close(fd); errno = e; return -1; }
    /* Keep the original stream send semantics. This timeout applies to a stalled
     * send in the presenter, not to the total time of a frame or to the UI. */
    const struct timeval timeout = { .tv_sec = 2 };
    if(setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)))
        slog("{\"build\":\"P031\",\"event\":\"surface_timeout_unavailable\",\"errno\":%d}", errno);
    return fd;
}
static int send_all(int fd, const void *buf, size_t len, size_t *sent){
    const char *p = buf;
    *sent = 0;
    while(len){
        ssize_t written = send(fd, p, len, 0);
        if(written < 0 && errno == EINTR) continue;
        if(written <= 0){ if(!written) errno = EPIPE; return -1; }
        *sent += (size_t)written;
        p += written;
        len -= (size_t)written;
    }
    return 0;
}
static void surface_close(void){
    if(surface_fd >= 0){ close(surface_fd); surface_fd = -1; slog("{\"build\":\"P018\",\"event\":\"surface_closed\",\"frames\":%lu}", frames_sent); }
}

static void *surface_presenter(void *arg){
    (void)arg;
    struct surface_frame active = {0};
    for(;;){
        pthread_mutex_lock(&sink_lock);
        while(!frame_pending) pthread_cond_wait(&surface_ready, &sink_lock);
        struct surface_frame previous = active;
        active = pending;
        pending = previous;
        frame_pending = 0;
        unsigned long replaced = frames_replaced;
        pthread_mutex_unlock(&sink_lock);

        if(!active.header.w){ surface_close(); continue; }
        if(surface_fd < 0){
            surface_fd = surface_connect();
            ++connects;
            slog("{\"build\":\"P031\",\"event\":\"surface_connect\",\"fd\":%d,\"errno\":%d,\"n\":%lu}",
                 surface_fd, surface_fd < 0 ? errno : 0, connects);
        }
        if(surface_fd < 0) continue;
        active.header.frame = (uint32_t)frames_sent;
        size_t bytes = (size_t)active.header.w * active.header.h * sizeof(*active.pixels);
        size_t header_sent, pixels_sent = 0;
        if(send_all(surface_fd, &active.header, sizeof(active.header), &header_sent) ||
           send_all(surface_fd, active.pixels, bytes, &pixels_sent)){
            int error = errno;
            if(++frames_dropped <= 8 || !(frames_dropped % 100))
                slog("{\"build\":\"P031\",\"event\":\"surface_send_failed\",\"errno\":%d,\"dropped\":%lu,\"replaced\":%lu,"
                     "\"header_sent\":%zu,\"pixels_sent\":%zu,\"bytes\":%zu}",
                     error, frames_dropped, replaced, header_sent, pixels_sent, bytes);
            /* A partly sent frame cannot be followed by another header on this stream. */
            surface_close();
            continue;
        }
        if(++frames_sent == 1 || !(frames_sent % 120))
            slog("{\"build\":\"P031\",\"event\":\"surface_progress\",\"sent\":%lu,\"replaced\":%lu,\"bytes\":%zu}",
                 frames_sent, replaced, bytes);
    }
    return NULL;
}

/* Start from the child bootstrap before Wine has installed its signal handlers. */
void pw_pop_surface_start(void);
void pw_pop_surface_start(void)
{
    sigset_t all, old;
    sigfillset(&all);
    int mask_error = pw_wine_pthread_sigmask(SIG_BLOCK, &all, &old);
    if(mask_error){
        slog("{\"build\":\"P030\",\"event\":\"surface_signal_mask_failed\",\"error\":%d,\"errno\":%d}",
             mask_error, errno);
        return;
    }

    pthread_t presenter;
    int create_error = pthread_create(&presenter, NULL, surface_presenter, NULL);
    int restore_error = pw_wine_pthread_sigmask(SIG_SETMASK, &old, NULL);
    slog("{\"build\":\"P030\",\"event\":\"surface_thread_start\",\"create_error\":%d,\"restore_error\":%d}",
         create_error, restore_error);
    if(create_error) return;

    pthread_detach(presenter);
    pthread_mutex_lock(&sink_lock);
    surface_started = 1;
    pthread_mutex_unlock(&sink_lock);
}

void *pw_wine_screen_memory(unsigned int width, unsigned int height){ (void)width; (void)height; return NULL; }
void pw_wine_vk_window_presented(unsigned long long hwnd){ (void)hwnd; }
int pw_hw_sink_vk_windows(unsigned long long *out, int max){ (void)out; (void)max; return 0; }
/* the driver falls back to this when layers are refused; layers are always accepted here, so this is never
 * the picture: report success without touching the display */
int pw_wine_present(const void *pixels, unsigned int width, unsigned int height, unsigned int stride){
    (void)pixels; (void)width; (void)height; (void)stride; return 0;
}
int pw_wine_layers(void){ return 1; }
void pw_wine_window_shown(void *hwnd, const char *class_name){
    __atomic_store_n(&shown_hwnd, (uint32_t)(uintptr_t)hwnd, __ATOMIC_RELAXED);
    slog("{\"build\":\"P018\",\"event\":\"window_shown\",\"hwnd\":\"%p\",\"class\":\"%s\"}", hwnd, class_name ? class_name : "");
}
void pw_wine_pointer_hidden(int hidden){ (void)hidden; }
int pw_wine_pointer_area(unsigned int width, unsigned int height){ (void)width; (void)height; return 0; }
int pw_wine_layer_images(void){ return 0; }
/* Window pixel buffers: NULL here makes the driver give up layers (hardware 2026-11-12: "gpu_layers_off alloc",
 * then CPU composition into pw_wine_present). Plain heap memory from this PRX's libc, the same allocator the
 * driver uses, so freeing any buffer it hands back is valid; 1 = freed here. */
void *pw_wine_layer_alloc(size_t bytes){ return calloc(1, bytes ? bytes : 1); }
int pw_wine_layer_free(void *pixels){ free(pixels); return 1; }
int pw_wine_next_input(struct PwWineInput *event){ (void)event; return 0; }
int pw_wine_input_fd(void){ return -1; }
/* the Vulkan runtime reports a program's frame rate to the title's HUD through the sink; this process draws no HUD */
void pw_wine_vk_fps(unsigned tenths);
void pw_wine_vk_fps(unsigned tenths){ (void)tenths; }

int pw_wine_present_layers(const struct pw_wine_layer *stack, unsigned int count, unsigned int width, unsigned int height){
    (void)width; (void)height;
    pthread_mutex_lock(&sink_lock);
    if(!surface_started){
        pthread_mutex_unlock(&sink_lock);
        return 0;
    }
    const struct pw_wine_layer *top = NULL;
    for(unsigned i = count; i-- > 0;)
        if(stack[i].pixels && !(stack[i].flags & PS5_LAYER_IMAGE) && stack[i].right > stack[i].left && stack[i].bottom > stack[i].top){ top = &stack[i]; break; }
    if(!top){
        pending.header.w = 0;
        frame_pending = 1;
        pthread_cond_signal(&surface_ready);
        pthread_mutex_unlock(&sink_lock);
        return 0;
    }
    int w = top->right - top->left, h = top->bottom - top->top;
    if(w > 1920 || h > 1080){ pthread_mutex_unlock(&sink_lock); return 0; }
    size_t pixels = (size_t)w * (size_t)h;
    if(pixels > pending.capacity){
        uint32_t *buffer = realloc(pending.pixels, pixels * sizeof(*pending.pixels));
        if(!buffer){ pthread_mutex_unlock(&sink_lock); return 0; }
        pending.pixels = buffer;
        pending.capacity = pixels;
    }
    for(int y = 0; y < h; y++){
        const uint32_t *row = top->pixels + (size_t)y * top->stride;
        uint32_t *out = pending.pixels + (size_t)y * w;
        for(int x = 0; x < w; x++){ uint32_t v = row[x]; out[x] = v == PS5_UNPAINTED ? 0xff202020u : v; }
    }
    if(frame_pending && pending.header.w) ++frames_replaced;
    pending.header = (struct pop_sep_frame){
        POP_SEP_FRAME_MAGIC, top->left, top->top, w, h, 0,
        __atomic_load_n(&shown_hwnd, __ATOMIC_RELAXED), 0
    };
    frame_pending = 1;
    pthread_cond_signal(&surface_ready);
    pthread_mutex_unlock(&sink_lock);
    return 0;
}
